<?php
declare(strict_types=1);use Acorn\SafetyHealthcheck\Assessment\{AssessmentService,AssessmentRepository};
final class AssessmentLifecycleTest extends IntegrationTestCase{public function test_raw_token_not_stored_and_profile_change_invalidates_hidden_answer():void{$service=new AssessmentService();$start=$service->start();global$wpdb;self::assertSame(0,(int)$wpdb->get_var($wpdb->prepare("SELECT COUNT(*) FROM {$wpdb->prefix}acorn_hc_assessments WHERE assessment_token_hash=%s",$start['token'])));$with=$this->profile(['risk_flags'=>['work_at_height']]);$service->updateProfile($start['token'],$with);$service->saveAnswer($start['token'],'WAH01_WORK_AT_HEIGHT','no');$without=$this->profile(['risk_flags'=>[]]);$state=$service->updateProfile($start['token'],$without);self::assertArrayNotHasKey('WAH01_WORK_AT_HEIGHT',$state->answers);self::assertNotNull((new AssessmentRepository)->findByToken($start['token']));}}
